void __fastcall MISSILES_SetDamageByElementType(::SGAMEDATA * pGame, D2UnitStrc * pMissile, D2UnitStrc * pTarget, D2DamageStrc * pDamageStruct, int nDuration) {
    if (!pMissile) {
      return;
    }

    eD2ElementalDamageType byElemType = D2Common::Units::Missile::GetElemTypeFromMissileId(pMissile->nClassId);
    switch (byElemType) {
      case ELEMENTAL_COLD:
        pDamageStruct->dwColdLength = nDuration;
      return;
      case ELEMENTAL_POISON:
        pDamageStruct->dwPoisLength = nDuration;
      return;
      case ELEMENTAL_STUN:
        pDamageStruct->dwStunLen = nDuration;
      return;
      case ELEMENTAL_BURNING:
        pDamageStruct->dwBurnLen = nDuration;
      return;
      case ELEMENTAL_FREEZE:
        pDamageStruct->dwFrzLength = nDuration;
    }
}

