    MISSILES_SpawnPeriodicRandom(pGame, nMissileCount, (int)pMissilesTxt->SubMissile1, 5, nSpawnInterval, pUnit);
    nClassId = MISSMODE_SrvDoFn01_BasicMissile(pGame, pUnit);
    return nClassId;
